import { useLoaderContextValue } from '../../../context/LoaderContext'
import { reInitiateLoader, updateLoader } from '../actions'

export const useReInitiateLoader = () => {
  const [, dispatch] = useLoaderContextValue()
  return () => dispatch(reInitiateLoader())
}

export const useUpdateLoader = () => {
  const [, dispatch] = useLoaderContextValue()
  return (payload = {}) => dispatch(updateLoader(payload))
}

export const useResetLoader = () => {
  const [, dispatch] = useLoaderContextValue()
  return (payload = {}) => dispatch(updateLoader(payload))
}
